 void HdrMode(){
  var iniItem=C<ComboBox>("HdrMethod").Items[0] as ComboBoxItem;if(iniItem!=null)iniItem.IsEnabled=current!=null&&current.Confirmed;
  if(current!=null&&!current.Confirmed&&C<ComboBox>("HdrMethod").SelectedIndex==0)C<ComboBox>("HdrMethod").SelectedIndex=1;bool reshade=C<ComboBox>("HdrMethod").SelectedIndex==1;
  C<StackPanel>("UeHdrControls").Visibility=reshade?Visibility.Collapsed:Visibility.Visible;
  C<Button>("RenoDx").Visibility=Visibility.Collapsed;
  C<Grid>("UeSettingsGrid").Visibility=reshade?Visibility.Collapsed:Visibility.Visible;var renoHost=C<Grid>("RenoInline");renoHost.Visibility=reshade?Visibility.Visible:Visibility.Collapsed;if(!homeMode&&reshade&&current!=null&&!RenoDxUi.IsBusy){renoHost.Children.Clear();if(!String.IsNullOrEmpty(current.Exe)&&File.Exists(current.Exe))renoHost.Children.Add(RenoDxUi.Embed(window,current));else if(current.ProtectedInstall)renoHost.Children.Add(Dialogs.Text(current.Evidence,16));}
  C<Button>("Apply").Visibility=homeMode||reshade||dlssMode?Visibility.Collapsed:Visibility.Visible;
  C<TextBlock>("HdrMethodInfo").Text=reshade?"Regola l’HDR nel menu ReShade / RenoDX in gioco. La scelta non rimuove le mod già installate.":"Regola l’HDR nel motore UE5. Se hai installato RenoDX, ripristinalo prima di tornare alla sola gestione UE5.";
 }
 void RefreshHome(){
  bool valid=current!=null&&!String.IsNullOrEmpty(current.Exe)&&File.Exists(current.Exe);C<Button>("HdrSection").IsEnabled=C<Button>("Dlss").IsEnabled=valid;
  C<TextBlock>("HdrCardStatus").Text=C<TextBlock>("DlssCardStatus").Text=current==null?"Select a game":"Not installed";
  C<TextBlock>("HdrCardMethod").Text=current==null?"Choose a game to see available HDR methods.":current.Confirmed?"Engine HDR or ReShade + RenoDX":"ReShade + compatible HDR mod";
  C<TextBlock>("DlssCardMethod").Text=valid?"OptiScaler setup for the selected game":"Select a valid game executable first.";
  bool hdr=false,dlss=false;
  if(valid){try{string folder=Path.GetDirectoryName(current.Exe);bool reshade=RenoDx.Loaders(folder).Count>0,reno=RenoDx.HasHdrAddon(current);hdr=reshade&&reno;if(hdr)C<TextBlock>("HdrCardStatus").Text="RenoDX installed";else if(reshade)C<TextBlock>("HdrCardStatus").Text="ReShade installed";
   if(!hdr&&!String.IsNullOrEmpty(current.Config)){string path=Path.Combine(current.Config,"GameUserSettings.ini");if(File.Exists(path)){string text=File.ReadAllText(path);hdr=Core.Sections(text).Any(section=>String.Equals(Core.Get(text,section,"bUseHDRDisplayOutput"),"true",StringComparison.OrdinalIgnoreCase));if(hdr)C<TextBlock>("HdrCardStatus").Text="Engine HDR configured";}}
  }catch(Exception ex){C<TextBlock>("HdrCardStatus").Text="Check required";C<TextBlock>("HdrCardStatus").ToolTip=ex.Message;}try{
   var scan=DlssCore.Inspect(current,false,false);dlss=scan.Proxy!="";C<TextBlock>("DlssCardStatus").Text=dlss?"OptiScaler installed":"Not installed";if(dlss)C<TextBlock>("DlssCardMethod").Text="Detected files · verify activation in game";
  }catch(Exception ex){C<TextBlock>("DlssCardStatus").Text="Check required";C<TextBlock>("DlssCardStatus").ToolTip=ex.Message;}}
  C<Button>("HdrSection").Style=window.TryFindResource(hdr?"Installed":"Primary") as Style;C<Button>("Dlss").Style=window.TryFindResource(dlss?"Installed":"Primary") as Style;Appearance.Refresh();
 }
 void UpdateLibraryLayout(){double height=window.ActualHeight>0?window.ActualHeight:window.Height;double poster=Math.Round(Math.Max(200,Math.Min(320,200+(height-740)*0.18)));window.Resources["LibraryPosterHeight"]=poster;window.Resources["LibraryCardWidth"]=Math.Round(poster*0.70+24);C<RowDefinition>("LibraryRow").Height=new GridLength(poster+225);C<ListBox>("Games").LayoutTransform=Transform.Identity;}
 void ShowHome(){if(RenoDxUi.IsBusy||(dlssPanel!=null&&dlssPanel.IsBusy))throw new Exception("Wait for the current operation to finish.");if(!homeMode&&!Leave())return;homeMode=true;C<Button>("Overview").Visibility=Visibility.Collapsed;UpdateLibraryLayout();C<ScrollViewer>("FeatureHome").Visibility=Visibility.Visible;C<Border>("HdrSettings").Visibility=Visibility.Collapsed;C<Grid>("DlssSection").Visibility=Visibility.Collapsed;C<Button>("Apply").Visibility=C<Button>("Overlay").Visibility=Visibility.Collapsed;RefreshHome();Appearance.Refresh();}
 void RenderDlss(){var host=C<Grid>("DlssSection");host.Children.Clear();host.RowDefinitions.Clear();dlssPanel=null;if(current==null)return;if(String.IsNullOrEmpty(current.Exe)||!File.Exists(current.Exe)){host.Children.Add(Dialogs.Text(current.ProtectedInstall?current.Evidence:"Scegli un target.exe valido dal pulsante Target.exe / API per configurare OptiScaler.",16));return;}dlssPanel=new DlssUi();dlssPanel.Create(window,current,true);dlssPanel.EmbeddedContent.Margin=new Thickness(18,16,18,16);host.Children.Add(dlssPanel.EmbeddedContent);}
 void SwitchSection(bool dlss){
  if(RenoDxUi.IsBusy||(dlssPanel!=null&&dlssPanel.IsBusy))throw new Exception("Attendi il completamento dell’installazione.");
  if(dlss&&current==null)return;
  if(dlss&&!dlssMode&&!Leave())return;
  var host=C<Grid>("DlssSection");
  if(dlss&&(homeMode||!dlssMode))RenderDlss();homeMode=false;C<Button>("Overview").Visibility=Visibility.Visible;UpdateLibraryLayout();C<ScrollViewer>("FeatureHome").Visibility=Visibility.Collapsed;
  dlssMode=dlss;host.Visibility=dlss?Visibility.Visible:Visibility.Collapsed;
  C<Grid>("LibrarySection").Visibility=Visibility.Visible;
  C<Border>("HdrSettings").Visibility=dlss?Visibility.Collapsed:Visibility.Visible;
  HdrMode();
  C<Button>("Overlay").Visibility=dlss?Visibility.Collapsed:Visibility.Visible;
  RefreshHome();Appearance.Refresh();
